SourceCode.Declaration:
/// <summary>
/// The service class for Return order regisration
/// </summary>
class METSalesOrderReturnCreditRegistrationService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// Return order register
    /// </summary>
    /// <param name="returnOrderRegistrationContract">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METSalesOrderReturnCreditRegistrationResponseContract</c>
    /// </returns>
    //[AifCollectionType('returnOrderRegistrationContract', Types::Class, classStr(METSalesOrderReturnCreditRegistrationContract))]
    public METSalesOrderReturnCreditRegistrationResponseContract returnOrderRegister(METSalesOrderReturnCreditRegistrationContract returnOrderRegistrationContract)
    {
        METProcessingStatus result;
        Description255      message = "@MET:NoRecordsUpdated"; //default message

        [result, message] = this.processReturnOrderRegister(returnOrderRegistrationContract);
        
        return METSalesOrderReturnCreditRegistrationResponseContract::newFromParameters(result, message);
    }

    /// <summary>
    /// Process the registration of return order lines
    /// </summary>
    /// <param name="_returnOrderRegistrationContract">List of contracts</param>
    /// <returns>Container of Results</returns>
    public container processReturnOrderRegister(METSalesOrderReturnCreditRegistrationContract _returnOrderRegistrationContract)
    {
        METProcessingStatus result;
        Description255      message = "@MET:NoRecordsUpdated";
        
        DataAreaId          dataAreaId;
        container           resultCon;

        try
        {
            dataAreaId = _returnOrderRegistrationContract.parmDataAreaId();

            changecompany(dataAreaId)
            {
                resultCon = this.returnOrderLineRegister(_returnOrderRegistrationContract);

                result = conPeek(resultCon, 1);
                message = conPeek(resultCon, 2);
            } 
        }
        catch
        {
            result = METProcessingStatus::Error;
            // Bug 215261: CB197 - Registration is failing for batch-enabled items when web services are used.
            // return exact error message instead of generic error
            //message = "@MET:ReturnOrderNotRegistered";
            message = Global::METGetErrorAndCLR();
        }
        
        return [result, message];
       
    }

    /// <summary>
    /// Register return order lines
    /// </summary>
    /// <param name = "_metSalesOrderReturnCreditRegistrationContract">Contract class reference</param>
    /// <returns>Container</returns>
    public container returnOrderLineRegister(metSalesOrderReturnCreditRegistrationContract _metSalesOrderReturnCreditRegistrationContract)
    {
        SalesTable                              salesTable;
        inventTrans                             inventTrans;
        inventTransOrigin                       inventTransOrigin;
        TradeOrderLineRegister                  tradeOrderlineRegister;
        SalesReturnOrderLineRegister            salesReturnOrderLineRegister;
        InventTransWMS_Register                 inventTransWMS_register;
        TmpInventTransWMS                       TmpInventTransWMS;
        SalesLine                               salesLineReg;
        Args                                    args = new Args();
        SalesReturnItemNum                      rmaNumber;
        LineNum                                 lineNumber;
        ReturnDispositionCodeId                 dispositionCodeId;
        METProcessingStatus                     result;
        Description255                          messageLoc;
        ItemId                                  itemNumber;

        rmaNumber = _metSalesOrderReturnCreditRegistrationContract.parmRMANumber();
        lineNumber = _metSalesOrderReturnCreditRegistrationContract.parmLineNumber();
        dispositionCodeId = METCustParameters::Find().DispositionCodeRegistration;
        itemNumber = _metSalesOrderReturnCreditRegistrationContract.parmItemNumber();

        if (dispositionCodeId == '')
        {
            result      = METProcessingStatus::Error;
            messageLoc  = "@MET:DispositionCodeNotConfigured";
 
            return [result, messageLoc];
        }

        ttsBegin;
        
        select firstonly salesTable where salesTable.ReturnItemNum == rmaNumber; // Not using field list because using same buffer in Business event. 

        select firstonly salesLineReg
            where salesLineReg.SalesId == salesTable.SalesId &&
                  salesLineReg.ItemId == itemNumber;

        if (salesLineReg.RecId != 0 && salesLineReg.ReturnStatus == ReturnStatusLine::Awaiting)
        {
            args.record(salesLineReg);

            tradeOrderLineRegister = SalesReturnOrderLineRegister::construct();
            tradeOrderLineRegister.parmArgs(args);
            tradeOrderLineRegister.init();
            salesReturnOrderLineRegister = tradeOrderLineRegister;
            salesReturnOrderLineRegister.runPreSuper();

            //update returnDisposioncode
            salesLineReg.ReturnDispositionCodeId = dispositionCodeId;
            salesLineReg.update();

            select firstOnly crossCompany inventTrans
                join RecId, InventTransId from inventTransOrigin
                    where inventTransOrigin.InventTransId == salesLineReg.InventTransId
                    && inventTrans.InventTransOrigin == inventTransOrigin.RecId;

            inventTransWMS_register = inventTransWMS_register::newStandard(tmpInventTransWMS);
            tmpInventTransWMS.clear();
            tmpInventTransWMS.initFromInventTrans(inventTrans);            
            tmpInventTransWMS.InventDimId = inventTrans.InventDimId;
            // Bug 215261: CB197 - Registration is failing for batch-enabled items when web services are used.
            // this is require to set the itemId which is failing in Class\InventTransWMS_Register\updateInventoryBatch
            tmpInventTransWMS.initFromInventTransOrigin(inventTrans.inventTransOrigin());
            tmpInventTransWMS.insert();
            inventTransWMS_register.writeTmpInventTransWMS(tmpInventTransWMS,
                                                        inventTrans,
                                                        inventTrans.inventDim());
            inventTransWMS_register.updateInvent(salesLineReg);

            // Bug 216784: CB871-Business event not supplying correct details.
            // Moving the business event trigger outside of custom service so it can be called from both UI and customer service
            /*select firstonly RecId from salesLineReg
                where salesLineReg.SalesId == salesTable.SalesId    &&
                    salesLineReg.ReturnStatus != ReturnStatusLine::Registered;

            if (salesLineReg.RecId == 0) // All lines are registered for the RMA
            {
                METSOReturnAndClaimsBusinessEvent::newFromSalesTable(salesTable).send();
            }*/

            result = METProcessingStatus::Success;
            messageLoc = "@MET:ReturnLineRegistered";
        }
        else
        {
            result = METProcessingStatus::Error;
            messageLoc = "@MET:ReturnOrderLineNotExists";
        }
        ttsCommit;

        return [result, messageLoc];
    }

/// <summary>
/// Construct method to create new instance
/// </summary>
/// <returns>METSalesOrderReturnCreditRegistrationService</returns>
Public static METSalesOrderReturnCreditRegistrationService construct()
{
    return new METSalesOrderReturnCreditRegistrationService();
}
